import pyomo.environ as pyo

DATA = {
    "animals": ["cow", "elephant"],
    "bricks_per_animal": {"cow": 20, "elephant": 50},
    "min_bricks": 1000,
    "elephant_vs_cow_factor": 1,   # elephant <= 1 * cow
    "cow_vs_elephant_factor": 2,   # cow <= 2 * elephant
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.ANIMALS = pyo.Set(initialize=d["animals"])

    # --- Variables ---
    model.animals = pyo.Var(
        model.ANIMALS,
        within=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # --- Objective: minimise total number of animals ---
    def obj_rule(m):
        return sum(m.animals[a] for a in m.ANIMALS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Constraint: at least min_bricks bricks transported ---
    def bricks_rule(m):
        return sum(
            d["bricks_per_animal"][a] * m.animals[a] for a in m.ANIMALS
        ) >= d["min_bricks"]

    model.bricks_constraint = pyo.Constraint(rule=bricks_rule)

    # --- Constraint: elephants cannot exceed cows ---
    def elephant_le_cow_rule(m):
        return (
            m.animals["elephant"]
            <= d["elephant_vs_cow_factor"] * m.animals["cow"]
        )

    model.elephant_le_cow = pyo.Constraint(rule=elephant_le_cow_rule)

    # --- Constraint: cows at most twice the elephants ---
    def cow_le_twice_elephant_rule(m):
        return (
            m.animals["cow"]
            <= d["cow_vs_elephant_factor"] * m.animals["elephant"]
        )

    model.cow_le_twice_elephant = pyo.Constraint(rule=cow_le_twice_elephant_rule)

    return model
